import { loadPyodide } from "pyodide";
import { fileURLToPath } from "node:url";
import fs from "node:fs";
import path from "node:path";

const repo = process.env.NOR_REPO || path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const argv = process.argv.slice(2);
const lean = argv.includes("--no-skimage-deps");
const finder = argv.find((a) => !a.startsWith("--")) || "tl";
const tif = path.join(repo, "data", "raw", "Left Up- Edited", "Slide5_4AP_NoR.sld - Slice1_up_left2.tif");
const MB = 2 ** 20;
let py, prev;

function filesBytes(dir = "/") {
  // sum of file sizes in MEMFS, skipping the NODEFS mount and the virtual dirs
  let n = 0;
  for (const e of py.FS.readdir(dir)) {
    if (e === "." || e === "..") continue;
    const p = (dir === "/" ? "" : dir) + "/" + e;
    if (["/repo", "/dev", "/proc", "/sys"].includes(p)) continue;
    const st = py.FS.lstat(p);
    if (py.FS.isDir(st.mode)) n += filesBytes(p);
    else if (py.FS.isFile(st.mode)) n += st.size;
  }
  return n;
}

function sample(label) {
  globalThis.gc?.();
  const m = process.memoryUsage();
  const wasm = py ? py._module.HEAPU8.length : 0;
  const files = py ? filesBytes() : 0;
  const r = { label, rss: m.rss, wasm, files, jsheap: m.heapUsed };
  r.rest = r.rss - r.wasm - r.files - r.jsheap;
  const d = prev ? r.rss - prev.rss : 0;
  console.log([label.padEnd(34), ...["rss", "wasm", "files", "jsheap", "rest"].map((k) => (r[k] / MB).toFixed(0).padStart(6)),
    ((d >= 0 ? "+" : "") + (d / MB).toFixed(0)).padStart(6)].join(" "));
  prev = r;
  return r;
}

console.log(["stage".padEnd(34), "rss", "wasm", "files", "jsheap", "rest", "Δrss"].map((s, i) => i ? s.padStart(6) : s).join(" "));
sample("node, nothing loaded");
py = await loadPyodide();
sample("pyodide runtime + stdlib");
const quiet = { messageCallback: () => {} };
const pkgFiles = {};
async function load(names, label) {
  const before = filesBytes();
  if (lean && names.includes("scikit-image")) {
    // the wheel alone: its declared dependencies are not imported by the finders
    await py.loadPackage(["lazy_loader", "packaging"], quiet);
    await py.loadPackage(py._api.lockfile_packages["scikit-image"].file_name
      ? new URL(py._api.lockfile_packages["scikit-image"].file_name, py._api.config.indexURL || import.meta.url).href : "scikit-image", { ...quiet, checkIntegrity: false });
  } else await py.loadPackage(names, quiet);
  pkgFiles[label] = filesBytes() - before;
  sample(`files: ${label}`);
}
await load(["numpy"], "numpy");
await load(["scipy"], "scipy");
await load(["scikit-image"], lean ? "scikit-image (no deps)" : "scikit-image + deps");
await load(["pillow"], "pillow");
await load(["micropip"], "micropip");
await py.pyimport("micropip").install("tifffile==2026.3.3");
sample("files: tifffile");

const imp = (code, label) => { py.runPython(code); return sample(label); };
imp("import numpy", "import numpy");
imp("from scipy import ndimage", "import scipy.ndimage");
imp("from skimage.segmentation import watershed; from skimage.morphology import reconstruction, h_maxima; from skimage.measure import perimeter; from skimage.filters import threshold_otsu", "import skimage (used parts)");
imp("from PIL import Image, ImageDraw", "import PIL");
imp("import tifffile", "import tifffile");
py.FS.mkdirTree("/repo");
py.FS.mount(py.FS.filesystems.NODEFS, { root: repo }, "/repo");
imp("import sys, os; sys.path[:0] = ['/repo/detection', '/repo/src']; os.environ['NORFINDER_SRC'] = '/repo/src'; import interactive", "import finders (interactive)");
const loaded = py.runPython("import sys; sorted(m.split('.')[0] for m in sys.modules)").toJs();
const tops = {}; for (const m of loaded) tops[m] = (tops[m] || 0) + 1;

py.FS.writeFile("/tmp/slide.tif", fs.readFileSync(tif));
sample("slide bytes in /tmp");
imp("S = interactive.Session('/tmp/slide.tif')", "open slide + blue mask");
imp("_img = S.images()", "images() for the page");
imp("del _img", "(images freed)");
imp(`meta, seg = S.detect('${finder}', {})`, `detect ${finder}`);
imp("_f = S.refilter({'values': {}, 'off': []})", "first refilter");
imp("del meta, seg; import gc; gc.collect()", "(detect outputs freed)");

console.log("\nfiles by package (MB):", Object.entries(pkgFiles).map(([k, v]) => `${k} ${(v / MB).toFixed(1)}`).join(", "));
console.log("python modules imported, by top-level package:", Object.entries(tops).filter(([, n]) => n > 5).sort((a, b) => b[1] - a[1]).map(([k, n]) => `${k} ${n}`).join(", "));
const libs = Object.keys(py._module.LDSO.loadedLibsByName).filter((k) => k.endsWith(".so"));
let soBytes = 0; const soBy = {};
for (const l of libs) {
  try {
    const s = py.FS.stat(l).size; soBytes += s;
    const top = (l.match(/site-packages\/([^/]+)/) || [, "other"])[1]; soBy[top] = (soBy[top] || 0) + s;
  } catch {}
}
console.log(`native modules loaded: ${libs.length}, ${(soBytes / MB).toFixed(1)} MB of wasm binary:`,
  Object.entries(soBy).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${(v / MB).toFixed(1)}`).join(", "));

