    return { secs: d.secs, cands: meta.cands.length, passes: f.fails.filter((x) => x === null).length };
  }, finder);
  await mark(`detect ${finder} + refilter (${res.secs.toFixed(1)} s)`);
} catch (e) { console.log(`stopped: ${e.message.split("\n")[0]}`); }
